import itemsjs from "itemsjs";
import { adaptFacetHits, adaptResponse } from "./adaptResponse";
import { adaptRequest } from "./adaptRequest";
import { collateSortings } from "./collateSortings";
import { SearchForFacetValuesResponse } from "@algolia/client-search";
import {
  AdapterOptions,
  IndexOptions,
  ItemsJsBucket,
  ItemsJsOptions,
  SearchClient,
  SearchForFacetValuesQuery,
  SearchRequest,
  SearchResponses,
} from "./itemsjsInterface";

let index;

// The searchableFields of each index made by createIndex, which hits are
// highlighted in unless the request sets attributesToHighlight
const searchableFields = new WeakMap<object, ReadonlyArray<string>>();

// The sortings of each index made by createIndex. Any other sort, such as the
// index name InstantSearch sends for relevance, is dropped so itemsjs keeps
// its relevance order and only fetches the requested page.
const sortingNames = new WeakMap<object, ReadonlySet<string>>();

export function getSearchClient(
  newIndex?: any,
  options?: AdapterOptions
): SearchClient {
  return {
    search: (queries: SearchRequest[]) =>
      performSearch(queries, index || newIndex, options),
    searchForFacetValues: (queries: SearchForFacetValuesQuery[]) =>
      searchForFacetValues(queries, index || newIndex, options),
  };
}

export function createIndex(
  data: object,
  options: ItemsJsOptions,
  indexOptions: IndexOptions = {}
): any {
  const { collator } = indexOptions;

  if (options.sortings && collator !== false && Array.isArray(data)) {
    options = {
      ...options,
      sortings: collateSortings(data, options.sortings, collator),
    };
  }

  index = itemsjs(data, options);
  searchableFields.set(index, options.searchableFields);
  sortingNames.set(index, new Set(Object.keys(options.sortings || {})));
  return index;
}

export function performSearch(
  requests: SearchRequest[],
  index: any,
  options?: AdapterOptions
): Readonly<Promise<SearchResponses>> {
  if (index) {
    let processingTimeMS = 0;
    const responses = requests.map((request) => {
      const adaptedRequest = adaptRequest(request, options);
      const sortings = sortingNames.get(index);
      if (sortings && !sortings.has(adaptedRequest.sort)) {
        delete adaptedRequest.sort;
      }

      const itemsJsRes = index.search(adaptedRequest);

      processingTimeMS = processingTimeMS + itemsJsRes.timings.total;

      // Are there any aggregations?
      if (itemsJsRes.data.aggregations) {
        // Only copy the requested aggregations
        const filteredAggregations = {};
        Object.keys(itemsJsRes.data.aggregations).forEach((aggregationName) => {
          if (request.params.facets.includes(aggregationName)) {
            filteredAggregations[aggregationName] =
              itemsJsRes.data.aggregations[aggregationName];
          }
        });

        itemsJsRes.data.aggregations = filteredAggregations;
      }

      return adaptResponse(
        itemsJsRes,
        request.params.query,
        processingTimeMS,
        request.params,
        searchableFields.get(index)
      );
    });

    return Promise.resolve({ results: responses });
  }

  return null;
}

export function performSearchForFacetValues(
  requests: SearchForFacetValuesQuery[],
  index: any,
  options?: AdapterOptions
): Readonly<Promise<ItemsJsBucket[][]>> {
  if (index) {
    const responses = requests.map((request) => {
      const { filter, ...input } = adaptRequest(request, options);

      // aggregation() JSON-clones its input, which drops the filter function
      // built from numericFilters and insideBoundingBox. Resolve query +
      // filter up front and pass the matching ids.
      if (filter) {
        const matches = index.search({
          query: input.query,
          filter,
          page: 1,
          per_page: Number.MAX_SAFE_INTEGER,
        });
        input.ids = matches.data.items.map((item) => item.id);
        delete input.query; // Ignored once ids are set; already applied above
      }

      const itemsJsRes = index.aggregation({
        ...input,
        name: request.params.facetName,
        page: 1,
        per_page: Number.MAX_SAFE_INTEGER,
      });

      return itemsJsRes.data.buckets;
    });

    return Promise.resolve(responses);
  }

  return null;
}

export function searchForFacetValues(
  requests: SearchForFacetValuesQuery[],
  index: any,
  options?: AdapterOptions
): Readonly<Promise<SearchForFacetValuesResponse[]>> {
  const results = performSearchForFacetValues(requests, index, options);

  if (results) {
    return results.then((responses) =>
      responses.map((buckets, i) => adaptFacetHits(buckets, requests[i].params))
    );
  }

  return null;
}
